"""Generate plugin agent persona surfaces from the baseline catalog (#1336)."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from .baseline_catalog import BaselineAgent, load_baseline_catalog

GENERATED_BANNER = (
    "<!-- PLATE-GENERATED:BEGIN agents-surface -->\n"
    "<!-- Do not edit generated agent surfaces manually. -->\n"
    "<!-- Source of truth: src/plate_core/data/baseline_catalog.yml -->\n"
    "<!-- Regenerate: python3 scripts/generate-plugin-agents.py -->\n"
)

GENERATED_FOOTER = "<!-- PLATE-GENERATED:END agents-surface -->\n"

REGENERATE_COMMAND = "python3 scripts/generate-plugin-agents.py"

PLUGIN_SURFACES = ("plugin", ".plugin")

# Hand-authored coordinator persona; not generated from catalog rows.
MANUAL_AGENT_FILES = frozenset({"plate.agent.md"})


@dataclass(frozen=True)
class PluginAgentsWriteResult:
    written_paths: tuple[Path, ...]
    removed_paths: tuple[Path, ...]


def _format_list(items: tuple[str, ...]) -> str:
    if not items:
        return "_None_"
    return "\n".join(f"- {item}" for item in items)


def render_agents_md(*, regenerate_command: str = REGENERATE_COMMAND) -> str:
    """Render the plugin-level AGENTS.md index from the baseline catalog."""
    catalog = load_baseline_catalog()
    agents = sorted(catalog.agents, key=lambda agent: agent.id)

    lines = [
        GENERATED_BANNER.rstrip(),
        "",
        "# PLATE Baseline Agents",
        "",
        "> **Do not edit this file manually.**",
        f"> Regenerate with: `{regenerate_command}`",
        "",
        "Canonical source: `src/plate_core/data/baseline_catalog.yml`",
        "",
        f"This catalog defines **{len(agents)}** narrow baseline roles (plus the hand-authored `plate` coordinator persona).",
        "Per-role Copilot payloads live under `agents/<id>.agent.md` in the same directory.",
        "",
        "## Index",
        "",
        "| ID | Name | Default MCP tool profiles |",
        "| --- | --- | --- |",
    ]

    for agent in agents:
        profiles = ", ".join(f"`{profile}`" for profile in agent.default_tool_profiles)
        lines.append(f"| `{agent.id}` | {agent.name} | {profiles} |")

    lines.extend(["", "## Details", ""])

    for agent in agents:
        lines.extend(_agent_detail_section(agent))
        lines.append("")

    lines.append(GENERATED_FOOTER.rstrip())
    return "\n".join(lines) + "\n"


def _agent_detail_section(agent: BaselineAgent) -> list[str]:
    skills = ", ".join(f"`{skill_id}`" for skill_id in agent.primary_skill_ids)
    profiles = ", ".join(f"`{profile}`" for profile in agent.default_tool_profiles)
    return [
        f"### `{agent.id}` — {agent.name}",
        "",
        agent.description,
        "",
        f"**Primary skills:** {skills}",
        "",
        f"**Default MCP tool profiles:** {profiles}",
        "",
        "**Constraints**",
        "",
        _format_list(agent.constraints),
        "",
        f"**Plugin agent file:** `agents/{agent.id}.agent.md`",
    ]


def render_agent_md(agent: BaselineAgent, *, regenerate_command: str = REGENERATE_COMMAND) -> str:
    """Render a Copilot-compatible per-role `.agent.md` payload."""
    skill_lines = "\n".join(f"- `{skill_id}`" for skill_id in agent.primary_skill_ids)
    profile_lines = "\n".join(f"- `{profile}`" for profile in agent.default_tool_profiles)
    constraint_lines = "\n".join(f"- {item}" for item in agent.constraints) or "- (none)"
    safe_description = agent.description.replace("\n", " ").strip()
    lines = [
        "---",
        f"name: {agent.id}",
        f"description: {safe_description}",
        "prompt_mode: full",
        "permission_mode: default",
        "agents_md: true",
        "---",
        "",
        GENERATED_BANNER.rstrip(),
        "",
        f"# {agent.name}",
        "",
        f"> Agent id: `{agent.id}`",
        f"> Generated from the baseline catalog. Regenerate with `{regenerate_command}`.",
        "",
        agent.description,
        "",
        "## Primary skills",
        "",
        skill_lines,
        "",
        "## Default MCP tool profiles",
        "",
        "Hosts should attach plate-mcp with these profiles (see `docs/mcp.md` and `PLATE_MCP_TOOL_PROFILES`):",
        "",
        profile_lines,
        "",
        "## Constraints",
        "",
        constraint_lines,
        "",
        "## Delegation",
        "",
        f"- CLI: `gh plate agents show {agent.id}` / `gh plate agents delegate {agent.id} \"<task>\"`",
        f"- MCP: `plate_agent` / `plate_delegate_to_agent` with `agent_id={agent.id}`",
        "",
        GENERATED_FOOTER.rstrip(),
    ]
    return "\n".join(lines) + "\n"


def expected_plugin_agent_paths(repo_root: Path) -> dict[Path, str]:
    catalog = load_baseline_catalog()
    root = repo_root.resolve()
    expected: dict[Path, str] = {}
    agents_md = render_agents_md()
    for surface in PLUGIN_SURFACES:
        base = root / surface
        expected[base / "AGENTS.md"] = agents_md
        for agent in catalog.agents:
            expected[base / "agents" / f"{agent.id}.agent.md"] = render_agent_md(agent)
    return expected


def write_plugin_agents_surfaces(
    repo_root: Path,
    *,
    dry_run: bool = False,
) -> PluginAgentsWriteResult:
    root = repo_root.resolve()
    expected = expected_plugin_agent_paths(root)
    written: list[Path] = []
    removed: list[Path] = []

    expected_files: set[Path] = set()
    for path in expected:
        if path.name.endswith(".agent.md"):
            expected_files.add(path)

    for surface in PLUGIN_SURFACES:
        agents_dir = root / surface / "agents"
        if not agents_dir.is_dir():
            continue
        for child in agents_dir.iterdir():
            if not child.is_file() or not child.name.endswith(".agent.md"):
                continue
            if child.name in MANUAL_AGENT_FILES:
                continue
            if child.resolve() not in {p.resolve() for p in expected_files}:
                if dry_run:
                    removed.append(child)
                else:
                    child.unlink()
                    removed.append(child)

    for path, content in sorted(expected.items(), key=lambda item: str(item[0])):
        if not dry_run:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
        written.append(path)

    return PluginAgentsWriteResult(tuple(written), tuple(removed))


def plugin_agents_surfaces_in_sync(repo_root: Path) -> tuple[bool, list[str]]:
    root = repo_root.resolve()
    errors: list[str] = []
    expected = expected_plugin_agent_paths(root)

    for path, content in sorted(expected.items(), key=lambda item: str(item[0])):
        rel = path.relative_to(root).as_posix()
        if not path.exists():
            errors.append(f"missing generated file: {rel}")
            continue
        actual = path.read_text(encoding="utf-8")
        if actual != content:
            errors.append(f"out of date generated file: {rel}")

    catalog = load_baseline_catalog()
    for surface in PLUGIN_SURFACES:
        agents_dir = root / surface / "agents"
        if not agents_dir.is_dir():
            continue
        expected_names = {f"{agent.id}.agent.md" for agent in catalog.agents}
        for child in agents_dir.iterdir():
            if not child.is_file() or not child.name.endswith(".agent.md"):
                continue
            if child.name in MANUAL_AGENT_FILES:
                continue
            if child.name not in expected_names:
                errors.append(f"unexpected generated agent file: {child.relative_to(root).as_posix()}")

    return (not errors, errors)
